package me.minis.ledger;
import java.util.*;import android.database.*;import android.database.sqlite.*;
public class Dedup368Test {
 static int checks;static SQLiteDatabase db;static long time;static void ok(boolean x,String why){checks++;if(!x)throw new AssertionError(why);}
 static void reset(){db.execSQL("DELETE FROM entries");db.execSQL("DELETE FROM finance");db.execSQL("DELETE FROM payment_pages");db.execSQL("DELETE FROM ignored_keys");}
 static void row(long id,String source,String key,long at,String kind,long cents,String merchant,String status,String semantic,String tx,String reason){db.execSQL("INSERT INTO entries VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",new Object[]{id,source,key,at,kind,cents,merchant,status,semantic,tx,reason,"fp"+id,"",0});}
 static PaymentParser.Result result(boolean known){PaymentParser.Result r=new PaymentParser.Result();r.kind="expense";r.cents=1200;r.merchant="合成餐饮店";r.receiptEvidence=true;r.transactionTime=known?time:0;r.reason=known?"历史凭证":"没有独立交易时间";return r;}
 static long match(String source,PaymentParser.Result r,boolean known,String tx){return ReceiptDedup.match(db,source,"generic-receipt:"+(known?"timed":"undated"),known?time:time+3600000,r,tx,0);}
 static long count(String where){try(Cursor c=db.rawQuery("SELECT count(*) FROM entries WHERE "+where,null)){c.moveToFirst();return c.getLong(0);}}
 public static void main(String[] args){TimeZone.setDefault(TimeZone.getTimeZone("Asia/Shanghai"));Calendar c=Calendar.getInstance();c.clear();c.set(2026,9,30,11,26);time=c.getTimeInMillis();db=new SQLiteDatabase(args[0]);db.execSQL("CREATE TABLE entries(_id INTEGER PRIMARY KEY,source TEXT,nkey TEXT,time INTEGER,kind TEXT,cents INTEGER,merchant TEXT,status TEXT,semantic TEXT,txkey TEXT,reason TEXT,fingerprint TEXT,funding TEXT,ignored_at INTEGER)");db.execSQL("CREATE TABLE finance(entry INTEGER,peer INTEGER,type TEXT)");db.execSQL("CREATE TABLE ignored_keys(token TEXT PRIMARY KEY)");PaymentPageDb.install(db);
 for(String pkg:new String[]{"com.tencent.mm","com.eg.android.AlipayGphone","com.unionpay","com.jingdong.app.mall","synthetic.other.app"}){
  String source=pkg+":screen";reset();row(1,source,"screen:old",time+23000,"expense",1200,"合成餐饮店","confirmed","user-edited","","");PaymentParser.Result r=result(true);
  ok(match(source,r,true,"")==1,pkg+" timed receipt skips confirmed user-edited row");ok(match(source,result(false),false,"")==1,pkg+" clipped card does not become current debit");
  row(2,source,"generic-receipt:old",time,"expense",1200,"合成餐饮店","review","auto","","历史凭证");ok(match(source,result(true),true,"")==1,"confirmed wins over pending copy");
  ok(ReceiptDedup.reconcile(db)==1,"old pending retired");ok(count("status='confirmed'")==1&&count("status='review'")==0,"confirmed untouched, review gone");ok(ReceiptDedup.reconcile(db)==0,"reconcile idempotent");
  r.checkout="new-purchase";ok(match(source,r,true,"")==0,"new checkout retained");r.checkout="";r.merchant="另一家店";ok(match(source,r,true,"")==0,"different merchant retained");r.merchant="合成餐饮店";r.kind="income";ok(match(source,r,true,"")==0,"different direction retained");r.kind="expense";r.cents=1500;ok(match(source,r,true,"")==0,"different amount retained");r.cents=1200;
  ok(match("other.source:screen",r,true,"")==0,"different source not amount merged");ok(match(source,result(false),false,"new-transaction-123")==0,"undated independent transaction id retained");
  reset();row(1,source,"screen:old",time,"expense",1200,"合成餐饮店","confirmed","auto","id-one","");ok(match(source,result(true),true,"id-two")==0,"different transaction id retained");
  reset();row(1,source,"screen:old",time,"expense",1200,"合成餐饮店","confirmed","auto","","");row(2,source,"screen:new",time+10000,"expense",1200,"合成餐饮店","confirmed","user-edited","","");ok(match(source,result(true),true,"")==0,"two independent same-minute payments ambiguous");
  reset();row(1,source,"screen:old",time-86400000,"expense",1200,"合成餐饮店","confirmed","auto","","");ok(match(source,result(false),false,"")==0,"previous day cannot swallow new card");
  reset();row(1,source,"screen:old",time,"expense",1200,"合成餐饮店","confirmed","auto","","");row(2,source,"generic-receipt:timed",time,"expense",1200,"合成餐饮店","review","user-edited","","历史凭证");ok(ReceiptDedup.reconcile(db)==0,"manually edited pending protected");
  db.execSQL("UPDATE entries SET semantic='auto' WHERE _id=2");for(String type:new String[]{"distinct","split","refund","case","settlement","taglink"}){db.execSQL("DELETE FROM finance");db.execSQL("INSERT INTO finance VALUES(?,?,?)",new Object[]{2,1,type});ok(ReceiptDedup.reconcile(db)==0,"financial relation protected "+type);}
  reset();row(1,source,"screen:old",time,"expense",1200,"合成餐饮店","confirmed","auto","","");r=result(true);r.receiptEvidence=false;ok(ReceiptDedup.match(db,source,"screen:new",time,r,"",0)==1,"generic timed page shares gate");
  reset();row(1,source,"screen:old",time,"expense",1200,"合成餐饮店","confirmed","auto","","");r=result(false);r.receiptEvidence=false;r.pageSignature="same-identity";r.pageFrame="exact-frame";PaymentPageDb.remember(db,source,time,r,1);ok(PaymentPageDb.apply(db,source,time+3600000,r),"same confirmed success page reopen suppressed");r.checkout="new-checkout";ok(!PaymentPageDb.apply(db,source,time+3600001,r),"new checkout same page allowed");
  reset();row(1,source,"screen:old",time,"expense",1200,"合成餐饮店","confirmed","auto","","");row(2,source,"screen:pending",time+3600000,"expense",1200,"合成餐饮店","review","auto","","");r=result(false);r.pageSignature="same-identity";r.pageFrame="exact-frame";r.checkout="original-action";PaymentPageDb.remember(db,source,time,r,1);r.checkout="";PaymentPageDb.remember(db,source,time+3600000,r,2);ok(ReceiptDedup.reconcile(db)==1,"all-source old identical-page pending retired");ok(count("status='confirmed'")==1,"page reconcile leaves confirmed untouched");
 }
 for(String pkg:new String[]{"com.tencent.mm","com.eg.android.AlipayGphone","com.unionpay","synthetic.other.app"}){PaymentParser.Result r=result(true);String raw="交易单号\nABCDEF1234567890\n支付时间：2026-10-30 11:26:00";TransactionIdentity.Info x=TransactionIdentity.identify(pkg,raw,time+3600000,r);ok(x.key.equals("provider|"+pkg+"|expense|ABCDEF1234567890"),"all sources transaction namespace");ok(x.time==time,"transaction time not observed time");}
 ok(TransactionIdentity.providerId("交易号：ABCDEF1234567890\n交易单号：ABCDEF1234567899").isEmpty(),"conflicting ids rejected");ok(TransactionTime.clock("中午12:07",time+7200000)>0,"noon clock");ok(TransactionTime.clock("上午\u00a011:26",time+7200000)==time,"unicode space");ok(TransactionTime.clock("上午11:26\u200b",time+7200000)==time,"zero width");ok(TransactionTime.labelled("下单时间：2026-10-30 11:26",time+7200000)==0,"order time not payment time");
 System.out.println("PASS "+checks+" cross-provider production dedup + real SQLite assertions");
 }
}
